#!/usr/bin/env python3
from pathlib import Path
import sys,json,zlib,base64,hashlib
if len(sys.argv)!=2: raise SystemExit("usage: patch-shishalove-1.1.78-visual-brand-confidence-speed-candidate.py <plugin-dir>")
root=Path(sys.argv[1])
payload=json.loads(zlib.decompress(base64.b64decode("")))
for rel,spec in payload.items():
    p=root/rel; data=p.read_bytes()
    if hashlib.sha256(data).hexdigest()!=spec["sha"]: raise SystemExit("unexpected live-acceptance 1.1.78 baseline: "+rel)
    lines=data.decode("utf-8").splitlines(keepends=True)
    for i1,i2,text in reversed(spec["ops"]): lines[i1:i2]=text.splitlines(keepends=True)
    p.write_text("".join(lines),encoding="utf-8")
for rel,sha in {
    "assets/customer.js":"bc3d794decaae688ae97ae3a19ff520b9fc71cefa8c332f8aab0d7372818b5d4",
    "assets/bridge.css":"e5601c1b1a7feea17b58615afdba6abd7612968564d9216cf9c22dd98fd31bc2"
}.items():
    if hashlib.sha256((root/rel).read_bytes()).hexdigest()!=sha: raise SystemExit("preservation lock failed: "+rel)
p=(root/"shishalove-app-bridge.php").read_text();m=(root/"assets/merchant.js").read_text()
for token in ["Version: 1.1.78","slb_visual_brand_consensus_178","slb_visual_exact_confidence_gate_178","slb_visual_fast_local_probe_178","query_decision_cache","brand_not_found","no_reliable_match","EXACT PRODUCT NOT FOUND","NO RELIABLE MATCH FOUND","SHOW VISUALLY SIMILAR PRODUCTS"]:
    if token not in p+m: raise SystemExit("missing candidate token: "+token)
if "Version: 1.1.79" in p: raise SystemExit("version bump forbidden")
print("Bridge 1.1.78 final Visual Search accuracy + speed candidate applied; version intentionally unchanged")
